SELECT d.dept_name, CASE WHEN d.dept_name IN ('Finance', 'Marketing') THEN 'core' ELSE 'other' END AS dept_name_group, COUNT(*) AS employee_count, MAX(e.salary) AS max_salary FROM employees e LEFT JOIN departments d ON d.id = e.dept_id GROUP BY d.dept_name, CASE WHEN d.dept_name IN ('Finance', 'Marketing') THEN 'core' ELSE 'other' END HAVING MAX(e.salary) >= 107000 ORDER BY max_salary, employee_count DESC, dept_name, dept_name_group LIMIT 50;
